                    self.uniffiCloneHandle(),
                    FfiConverterDouble.lower(lat),FfiConverterDouble.lower(lng),FfiConverterOptionDouble.lower(accuracyMeters)
                )
            },
            pollFunc: ffi_pingolin_mobile_rust_future_poll_rust_buffer,
            completeFunc: ffi_pingolin_mobile_rust_future_complete_rust_buffer,
            freeFunc: ffi_pingolin_mobile_rust_future_free_rust_buffer,
            liftFunc: FfiConverterSequenceTypeBoundaryCrossing.lift,
            errorHandler: nil
            
        )
}
    
    /**
     * Drop every boundary and all inside/outside state
     */
open func clearBoundaries()async   {
