            freeFunc: ffi_pingolin_mobile_rust_future_free_void,
            liftFunc: { $0 },
            errorHandler: nil
            
        )
}
    
open func clearCallback()async   {
    return
        try!  await uniffiRustCallAsync(
            rustFutureFunc: {
                uniffi_pingolin_mobile_fn_method_boundarychecker_clear_callback(
                    self.uniffiCloneHandle()
                    
                )
            },
            pollFunc: ffi_pingolin_mobile_rust_future_poll_void,
            completeFunc: ffi_pingolin_mobile_rust_future_complete_void,
            freeFunc: ffi_pingolin_mobile_rust_future_free_void,
