            errorHandler: nil
            
        )
}
    
    /**
     * Metres from the fix to the boundary's CENTRE (not to its edge), or `None`
     * if no such boundary is loaded.
     */
open func distanceToBoundary(boundaryId: String, lat: Double, lng: Double)async  -> Double?  {
    return
