            completeFunc: ffi_pingolin_mobile_rust_future_complete_rust_buffer,
            freeFunc: ffi_pingolin_mobile_rust_future_free_rust_buffer,
            liftFunc: FfiConverterOptionDouble.lift,
            errorHandler: nil
            
        )
}
    
    /**
     * Get all boundary IDs the user is currently inside
     */
open func getBoundariesInside()async  -> [String]  {
    return
        try!  await uniffiRustCallAsync(
            rustFutureFunc: {
                uniffi_pingolin_mobile_fn_method_boundarychecker_get_boundaries_inside(
                    self.uniffiCloneHandle()
                    
                )
            },
            pollFunc: ffi_pingolin_mobile_rust_future_poll_rust_buffer,
