#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBoundaryChecker: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = BoundaryChecker

    public static func lift(_ handle: UInt64) throws -> BoundaryChecker {
        return BoundaryChecker(unsafeFromHandle: handle)
    }

    public static func lower(_ value: BoundaryChecker) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BoundaryChecker {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: BoundaryChecker, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeBoundaryChecker_lift(_ handle: UInt64) throws -> BoundaryChecker {
    return try FfiConverterTypeBoundaryChecker.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeBoundaryChecker_lower(_ value: BoundaryChecker) -> UInt64 {
    return FfiConverterTypeBoundaryChecker.lower(value)
}






/**
 * E2EE Boundary Monitor
 *
 * Monitors circle members' locations for boundary crossings while maintaining
 * end-to-end encryption. All decryption and checking happens on-device.
 */
public protocol BoundaryMonitorProtocol: AnyObject, Sendable {
    
    /**
     * Check this device's own location against every loaded place.
     *
     * Delegates to the underlying `BoundaryChecker`, so the exit margin, the
     * accuracy gate and first-observation priming described there apply here —
     * but not to `process_member_location`, which has its own simpler detector.
     *
     * `accuracy_meters` is optional and defaults to `None` (unknown, and so
     * evaluated); see `BoundaryChecker::check_location`.
     */
    func checkOwnLocation(lat: Double, lng: Double, accuracyMeters: Double?) async  -> [BoundaryCrossing]
    
    func clearCallback() async 
    
    /**
     * Clear all display names (call on logout)
     */
    func clearDisplayNames() async 
    
    /**
     * Get the display name for a user, falling back to user_id if not set
     */
    func getDisplayName(userId: String) async  -> String
    
    func getMonitoredUsers() async  -> [String]
    
    /**
     * user_id -> the circle_ids that user is monitored through
     */
    func getMonitoredUsersWithCircles() async  -> [String: [String]]
    
    /**
     * Load encrypted places and decrypt them using circle keys
     *
     * Call this when places are fetched from the server.
     */
    func loadEncryptedPlaces(places: [EncryptedPlace]) async throws  -> UInt32
    
    /**
     * Add a user to monitor for boundary crossings
     *
     * The user must be in a shared circle so their location can be decrypted.
     */
    func monitorUser(userId: String, circleId: String) async 
    
    /**
     * Total places loaded across all circles
     */
    func placeCount() async  -> UInt32
    
    /**
     * Process an encrypted location update from a circle member
     *
     * This decrypts the location, checks against all boundaries for that circle,
     * and triggers callbacks for any crossings detected.
     */
    func processMemberLocation(memberLocation: EncryptedMemberLocation) async throws  -> [BoundaryCrossing]
    
    /**
     * Set the callback for boundary events
     */
    func setCallback(callback: BoundaryMonitorCallback) async 
    
    /**
     * Name a user for notification text; call when circle members are loaded,
     * otherwise notifications fall back to the raw user_id.
     */
    func setDisplayName(userId: String, displayName: String) async 
    
    /**
     * Merge in several display names at once (existing entries are overwritten)
     */
    func setDisplayNames(names: [String: String]) async 
    
    /**
     * Stop monitoring a user and forget their inside/outside state, so a later
     * re-monitor starts from a clean slate rather than a stale one.
     */
    func unmonitorUser(userId: String) async 
    
}
