        self.sharingPublicKeyHex = sharingPublicKeyHex
        self.signingPublicKeyHex = signingPublicKeyHex
        self.confirmed = confirmed
        self.listed = listed
        self.listedRole = listedRole
        self.statements = statements
        self.personConfirmedKeys = personConfirmedKeys
        self.serverSaysKeyless = serverSaysKeyless
    }

    
}

