@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAuthMethod: FfiConverterRustBuffer {
    typealias SwiftType = AuthMethod

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AuthMethod {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .fileUpload(mimeTypes: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 2: return .takeoutLink(externalUrl: try FfiConverterString.read(from: &buf), mimeTypes: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 3: return .oAuth2Pkce(try FfiConverterTypeOAuthConfig.read(from: &buf)
        )
        
        case 4: return .credentials(fields: try FfiConverterSequenceTypeCredentialField.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AuthMethod, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .fileUpload(mimeTypes):
            writeInt(&buf, Int32(1))
            FfiConverterSequenceString.write(mimeTypes, into: &buf)
            
        
        case let .takeoutLink(externalUrl,mimeTypes):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(externalUrl, into: &buf)
            FfiConverterSequenceString.write(mimeTypes, into: &buf)
            
        
        case let .oAuth2Pkce(v1):
            writeInt(&buf, Int32(3))
            FfiConverterTypeOAuthConfig.write(v1, into: &buf)
            
        
        case let .credentials(fields):
            writeInt(&buf, Int32(4))
            FfiConverterSequenceTypeCredentialField.write(fields, into: &buf)
            
        }
    }
}


