/**
 * Callback for platform-specific background operations
 */
public protocol BackgroundMonitorPlatform: AnyObject, Sendable {
    
    /**
     * Show a local notification for a boundary crossing
     */
    func showLocalNotification(title: String, body: String, data: String) 
    
    /**
     * Request the server to send a push notification to the subscriber
     * This is used when the monitoring client detects a crossing
     */
    func requestServerNotification(placeId: String, crossingUserId: String, eventType: String) 
    
    /**
     * Called when the monitor needs to fetch latest locations from server
     */
    func fetchLatestLocations(circleIds: [String]) 
    
    /**
     * Persist monitoring state to storage (for app restart recovery)
     */
    func persistState(stateJson: String) 
    
    /**
     * Load the JSON last handed to `persist_state`, or `None` on a first run
     */
    func loadPersistedState()  -> String?
    
}


// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceBackgroundMonitorPlatform {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceBackgroundMonitorPlatform] = [UniffiVTableCallbackInterfaceBackgroundMonitorPlatform(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterCallbackInterfaceBackgroundMonitorPlatform.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface BackgroundMonitorPlatform: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterCallbackInterfaceBackgroundMonitorPlatform.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface BackgroundMonitorPlatform: handle missing in uniffiClone")
            }
